mapper.select:
SELECT p.*, m.name AS mcc_name, m.mcc_id AS mcc_code, sp.name AS sales_person_name, (SELECT COUNT(*) FROM product_assets pa WHERE pa.product_id = p.id) AS asset_count, (SELECT COUNT(*) FROM accounts ac WHERE ac.mcc_id = p.mcc_id AND ac.deleted_at IS NULL) AS related_account_count FROM products p LEFT JOIN mcc m ON p.mcc_id = m.id LEFT JOIN sales_persons sp ON p.sales_person_id = sp.id
p.owner_id = #{ownerId} AND p.deleted_at IS NULL
AND (p.product_name LIKE CONCAT('%', #{search}, '%') OR p.customer LIKE CONCAT('%', #{search}, '%'))
AND p.region = #{region}
AND p.status = #{status}
ORDER BY p.created_at DESC
